script:
// ---------- 1) BEÁLLÍTÁS / SETUP ----------
stage(1000, 600, "#14161c");
title({hu: "Sugárkövetés: kocka és padló", en: "Ray tracing: cube and floor"}, {color: "#e8ecf4"});

param("cell", {hu: "Pixelméret (kisebb = élesebb, lassabb)", en: "Pixel size (smaller = sharper, slower)"}, 4, 20, 10, 1, "px");
param("spin", {hu: "Kocka forgása", en: "Cube spin"}, -180, 180, 35, 5, "°/s");
param("cam",  {hu: "Kamera körbeforgatása", en: "Camera orbit"}, -90, 90, 20, 1, "°");
param("lightA", {hu: "Fény iránya", en: "Light direction"}, -180, 180, 50, 5, "°");
param("rf", {hu: "Padló tükrözése", en: "Floor reflectivity"}, 0, 0.9, 0.35, 0.05, "");
param("rc", {hu: "Kocka tükrözése", en: "Cube reflectivity"}, 0, 0.9, 0.2, 0.05, "");
param("bounce", {hu: "Visszaverődések száma", en: "Max reflection bounces"}, 0, 3, 2, 1, "");
toggle("shadow", {hu: "Árnyékok", en: "Shadows"}, true);

// --- állandók / constants ---
const X0 = 100, Y0 = 80, W0 = 800, H0 = 500;     // a kiszámolt kép: bal felső sarok és méret (px) / the rendered picture: top-left corner and size (px)
const CUBE_C = [0, 2.1, 0];                      // a kocka középpontja (m); a kocka éle 2, így a padló fölött lebeg / cube centre (m); the cube has edge 2, so it hovers above the floor
const TILT = deg(35);                            // a kocka állandó megdöntése, hogy a csúcsai látsszanak / fixed tilt of the cube so it shows its corners

// a lapok színe (lineáris 0…1); index = tengely*2 + (0 a −, 1 a + oldalra) / face colours (linear 0…1); index = axis*2 + (0 for the −side, 1 for the +side)
const FACE = [[0.85, 0.2, 0.2], [0.2, 0.4, 0.9], [0.2, 0.75, 0.35],
              [0.95, 0.6, 0.15], [0.65, 0.3, 0.85], [0.15, 0.75, 0.75]];
const HORIZON = [0.82, 0.88, 0.96];              // az ég színe a horizonton (ködként is ezt használja) / sky colour at the horizon (also used as fog)
const ZENITH = [0.35, 0.55, 0.9];                // az ég színe egyenesen felfelé / sky colour straight up

let ang = 0;                                     // a kocka elfordulási szöge (rad) / spin angle of the cube (rad)

// --- apró vektorműveletek ([x, y, z] tömbök) / tiny vector helpers (arrays [x, y, z]) ---
const add3 = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const sub3 = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const mul3 = (a, k) => [a[0] * k, a[1] * k, a[2] * k];
const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross3 = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const norm3 = a => mul3(a, 1 / max(sqrt(dot3(a, a)), 1e-12));

// Sugár–kocka metszés („réteg-módszer”). A kockát három tengelye írja le (axs, egységvektorok). / Ray–cube intersection ("slab method"). The cube is described by its three axes axs (unit vectors).
// A kocka saját rendszerében ez az |x|,|y|,|z| ≤ 1 doboz. Eredménye null vagy {t, n, k, s}: / In the cube's own frame it is the box |x|,|y|,|z| ≤ 1. Returns null or {t, n, k, s}:
// t = távolság a sugár mentén, n = kifelé mutató normális, k = az eltalált lap tengelye, s = oldal (+1 vagy −1). / t = distance along the ray, n = outward normal, k = axis of the face hit, s = side (+1 or −1).
function hitCube(o, d, axs) {
  const oc = sub3(o, CUBE_C);
  let tmin = -1e9, tmax = 1e9, kk = 0, ns = 1;
  for (let k = 0; k < 3; k++) {
    const lo = dot3(oc, axs[k]), ld = dot3(d, axs[k]);     // a sugár kezdőpontja és iránya a kocka rendszerében / ray origin and direction in the cube frame
    if (abs(ld) < 1e-9) { if (abs(lo) > 1) return null; continue; }   // párhuzamos ezzel a lappárral / parallel to this pair of faces
    let t1 = (-1 - lo) / ld, t2 = (1 - lo) / ld;           // hol metszi a sugár a két lapot / where the ray crosses the two faces
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    if (t1 > tmin) { tmin = t1; kk = k; ns = ld > 0 ? -1 : 1; }   // a belépési lap és normálisának oldala / entry face and its normal side
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;                          // a sugár elkerüli a dobozt / the ray misses the box
  }
  if (tmin < 1e-4) return null;                            // a kezdőpont mögött van / behind the origin
  return {t: tmin, n: mul3(axs[kk], ns), k: kk, s: ns};
}

// Egy sugár követése, eredménye a színe [r, g, b] (0…1). depth = eddigi visszaverődések száma. / Follow one ray and return its colour [r, g, b] (0…1). depth = how many reflections already happened.
function trace(o, d, depth, axs, lightP) {
  const hc = hitCube(o, d, axs);
  let tf = 1e9;                                            // távolság a padló síkjáig (y = 0) / distance to the floor plane y = 0
  if (d[1] < -1e-9) { const tt = -o[1] / d[1]; if (tt > 1e-4) tf = tt; }

  // ----- a kocka van a legközelebb / the cube is the nearest thing -----
  if (hc && hc.t < tf) {
    const p = add3(o, mul3(d, hc.t)), n = hc.n;
    const pc = sub3(p, CUBE_C);
    const k1 = (hc.k + 1) % 3, k2 = (hc.k + 2) % 3;        // a másik két tengely → helyzet a lapon / the two other axes → position on the face
    const edge = max(abs(dot3(pc, axs[k1])), abs(dot3(pc, axs[k2]))) > 0.9 ? 0.55 : 1;   // sötét szegély a széleken / dark rim at the edges
    const col = FACE[hc.k * 2 + (hc.s > 0 ? 1 : 0)];
    const lv = norm3(sub3(lightP, p));                     // irány a fényforrás felé / direction towards the light
    const nl = max(0, dot3(n, lv));                        // Lambert: a fénnyel bezárt szög koszinusza / Lambert: cos of the angle to the light
    const hv = norm3(sub3(lv, d));                         // felező vektor a csillanáshoz / half vector for the specular highlight
    const spec = nl > 0 ? 0.5 * pow(max(0, dot3(n, hv)), 50) : 0;
    let out = col.map(c => c * (0.22 + 0.78 * nl) * edge + spec);   // 0,22 = szórt (környezeti) fény / 0.22 = ambient light
    if (depth < P.bounce && P.rc > 0) {                    // tükrözés: r = d − 2(d·n)n / mirror reflection: r = d − 2(d·n)n
      const rd = sub3(d, mul3(n, 2 * dot3(d, n)));
      const rcol = trace(add3(p, mul3(n, 1e-3)), rd, depth + 1, axs, lightP);
      out = out.map((c, i) => c * (1 - P.rc) + rcol[i] * P.rc);
    }
    return out;
  }

  // ----- a padló van a legközelebb / the floor is the nearest thing -----
  if (tf < 1e9) {
    const p = add3(o, mul3(d, tf));
    const dark = mod(floor(p[0]) + floor(p[2]), 2) === 1;  // sakktábla 1 m-es mezőkkel / checkerboard with 1 m squares
    const base = dark ? [0.2, 0.22, 0.27] : [0.85, 0.85, 0.88];
    const lv = norm3(sub3(lightP, p));
    let lit = max(0, lv[1]);                               // a padló normálisa (0,1,0), így n·l = lv.y / floor normal is (0,1,0), so n·l = lv.y
    if (P.shadow && lit > 0) {                             // árnyéksugár: eltakarja-e a kocka a fényt? / shadow ray: does the cube block the light?
      const hs = hitCube([p[0], p[1] + 1e-3, p[2]], lv, axs);
      const dl = sqrt(dot3(sub3(lightP, p), sub3(lightP, p)));
      if (hs && hs.t < dl) lit = 0;
    }
    let out = base.map(c => c * (0.25 + 0.75 * lit));
    if (depth < P.bounce && P.rf > 0) {                    // tükröződés a padlón (az y összetevő előjelet vált) / floor reflection (flip the y component)
      const rcol = trace([p[0], 1e-3, p[2]], [d[0], -d[1], d[2]], depth + 1, axs, lightP);
      out = out.map((c, i) => c * (1 - P.rf) + rcol[i] * P.rf);
    }
    const fog = 1 - exp(-tf / 45);                         // a távoli padló beleolvad a horizont színébe / far floor fades into the horizon colour
    return out.map((c, i) => c * (1 - fog) + HORIZON[i] * fog);
  }

  // ----- semmit nem talált el: az ég színátmenete / nothing hit: sky gradient -----
  const s = clamp(d[1] * 1.6, 0, 1);
  return HORIZON.map((c, i) => c * (1 - s) + ZENITH[i] * s);
}

// ---------- 2) FIZIKA / PHYSICS ----------
update(dt => { ang += deg(P.spin) * dt; });              // az elfordulási szög ω·Δt-vel nő / spin angle grows by ω·Δt

// ---------- 3) RAJZOLÁS (a sugárkövető) / DRAWING (the ray tracer) ----------
draw(t => {
  const cell = P.cell;
  const nx = floor(W0 / cell), ny = floor(H0 / cell);     // pixelek száma vízszintesen / függőlegesen / number of pixels across / down
  const ox = X0 + (W0 - nx * cell) / 2;                   // a kép középre igazítása a keretben / centre the picture in its frame

  // a kamera a célpont körül kering / camera orbits around the target point
  const yc = deg(P.cam);
  const eye = [8 * sin(yc), 3.2, 8 * cos(yc)];
  const f = norm3(sub3([0, 1.3, 0], eye));                // előre / forward
  const rt = norm3(cross3(f, [0, 1, 0]));                 // jobbra / right
  const up = cross3(rt, f);                               // fel / up
  const tanH = tan(deg(24)), asp = W0 / H0;               // függőleges látószög 48°, oldalarány / vertical field of view 48°, aspect ratio

  // a fényforrás helye (pontszerű fény, 7 m magasan, körbejár) / light position (point light, 7 m up, circling around)
  const la = deg(P.lightA);
  const lightP = [6 * cos(la), 7, 6 * sin(la)];

  // a kocka tengelyei a világban: először döntés az x körül, aztán forgatás az y körül / cube axes in the world: first tilt about x, then spin about y
  const ca = cos(ang), sa = sin(ang), ct = cos(TILT), st = sin(TILT);
  const rotv = v => {
    const y1 = v[1] * ct - v[2] * st, z1 = v[1] * st + v[2] * ct;
    return [v[0] * ca + z1 * sa, y1, -v[0] * sa + z1 * ca];
  };
  const axs = [rotv([1, 0, 0]), rotv([0, 1, 0]), rotv([0, 0, 1])];

  rect(X0 - 4, Y0 - 4, W0 + 8, H0 + 8, {fill: "#000", stroke: "#3a3f4d", lw: 2});   // keret / frame

  for (let j = 0; j < ny; j++) {
    for (let i = 0; i < nx; i++) {
      const u = ((i + 0.5) / nx * 2 - 1) * asp * tanH;    // a pixel helye a képsíkon / pixel position on the image plane
      const v = (1 - (j + 0.5) / ny * 2) * tanH;
      const d = norm3(add3(f, add3(mul3(rt, u), mul3(up, v))));   // az elsődleges sugár iránya / primary ray direction
      const c = trace(eye, d, 0, axs, lightP);
      const r = floor(255 * sqrt(clamp(c[0], 0, 1)));     // a gyökvonás ≈ gammakorrekció / sqrt ≈ gamma correction
      const g = floor(255 * sqrt(clamp(c[1], 0, 1)));
      const b = floor(255 * sqrt(clamp(c[2], 0, 1)));
      rect(ox + i * cell, Y0 + j * cell, cell + 1, cell + 1, {fill: `rgb(${r},${g},${b})`, stroke: null});
    }
  }

  show({hu: "Pixelek száma", en: "Pixel count"}, nx * ny, "", 0);
  show({hu: "Kocka elfordulása", en: "Cube rotation"}, mod(todeg(ang), 360), "°", 0);
});
